(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['home','随时，听你说','首页'],['voice','一句话，自然回应','语音对话'],['history','让对话有迹可循','会话记录'],['record','留住此刻的灵感','录音'],['transcript','录音，一页整理','录音整理'],['settings','按你的习惯来','设置'],['api','连接你的智能','服务连接']];
const descriptions={field:['在手表上逐项配置。','每屏编辑一个字段。保存后回到服务设置；右滑放弃当前修改并返回。'],menu:['只留必要的操作。','纵向滚动浏览功能，右滑返回上一层。大按钮居中排列，避免圆弧边缘误触。'],home:['有想法，直接说。','轻触粒子球开始对话。紫蓝粒子构成缓慢旋转的球体，让等待也有呼吸感。'],voice:['每个状态，都看得见。','连接时散为光环，聆听时随节奏起伏，思考时聚合，回答时流动。轻触粒子球演示下一步。'],history:['接着上一次聊。','独立保留每段对话。可以新建会话、打开历史，也可以仅清空当前会话。'],record:['先记录，再整理。','开始、暂停、继续与结束，专注一个任务。离开录音页会结束计时。'],transcript:['把声音变成文字。','演示转写支持编辑和复制；保存后的文字将用于生成摘要。'],summary:['重点，一眼看清。','摘要与完整原文合并在录音整理页，轻触标签切换。'],settings:['少一点设置，多一点自在。','常用偏好集中管理。服务连接单独成页，不干扰语音主流程。'],api:['连接你习惯的服务。','地址、密钥、模型都在手表上逐项输入。每屏一个字段，保存后返回配置页，右滑取消。']};
let resultTab='summary';let fieldName='url';let page='home',orb,voice='idle',muted=false,speaker=true,recording=false,seconds=0,recordInterval=null,voiceTimeout=null,toastTimeout=null,editing=false;
let transcript='今天的产品评审确定：新版以粒子球作为语音入口，优先保证圆屏上的文字可读性。周三完成交互原型，周五进行手表实机测试。设计负责人确认页面，开发负责人检查动画性能。';
let threads=[{id:1,title:'今天的灵感',messages:[{role:'user',text:'帮我规划一下今天的工作。'},{role:'assistant',text:'先完成最重要的一件事，再为沟通和整理留出时间。需要我帮你拆分任务吗？'}]},{id:2,title:'周末出行',messages:[{role:'user',text:'周末想去附近走走。'},{role:'assistant',text:'可以安排一次半日公园散步，留出休息时间，出发前再确认天气。'}]}],active=1,config={url:'',key:'',model:''},haptics=true;
const fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('toast-show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('toast-show'),2200);}
function head(t){return `<div class="page-head"><button class="back" data-action="back" aria-label="返回">‹</button><h3>${t}</h3></div>`;}
function stopRecord(){clearInterval(recordInterval);recordInterval=null;recording=false;}
function stopVoice(){clearTimeout(voiceTimeout);voiceTimeout=null;voice='idle';}
function show(p){if(p==='summary'){resultTab='summary';p='transcript';}clearTimeout(toastTimeout);$('#toast').classList.remove('toast-show');if(p!=='field'&&!pages.some(x=>x[0]===p))p='home';if(page==='record'&&p!=='record')stopRecord();if(page==='voice'&&p!=='voice')stopVoice();orb?.destroy();page=p;history.replaceState(null,'',`#${p}`);render();}
function canvas(){return '<canvas aria-hidden="true"></canvas>';}
function render(){const index=page==='field'?6:page==='chat'?2:pages.findIndex(x=>x[0]===page);$('#chapter').textContent=`0${index+1} / 07`;$('#pageLabel').textContent=page==='chat'?'让想法接着发生':pages[index][1];$('#detailTitle').textContent=descriptions[page][0];$('#detailText').textContent=descriptions[page][1];$('#nav').innerHTML=pages.map(([id,,title],i)=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span>0${i+1}</span>${title}</button>`).join('');let html='';
if(page==='home')html=`<div class="home wrist-home"><div class="kicker">NOVA</div><button class="orb-button" data-action="startVoice" aria-label="开始语音对话">${canvas()}</button><h3>轻触，说出想法</h3><div class="gesture-hint">上下左右滑动切换</div><div class="page-dots" aria-hidden="true">● · · ·</div></div>`;
if(page==='voice')html=`<div class="voice"><div class="kicker" id="voiceBadge"></div><button class="orb-button" data-action="nextVoice" aria-label="切换语音演示状态">${canvas()}</button><h3 id="voiceTitle"></h3><div class="voice-caption" id="voiceCaption"></div><div class="timer" id="voiceTimer">演示对话</div><div class="voice-controls"><button class="round ${muted?'off':''}" data-action="mute" aria-label="${muted?'开启':'关闭'}麦克风">♩</button><button class="round end" data-action="endVoice" aria-label="结束对话">×</button><button class="round ${speaker?'':'off'}" data-action="speaker" aria-label="${speaker?'关闭':'开启'}扬声器">◖</button></div></div>`;
if(page==='history')html=`<div class="wrist-list"><h3>最近对话</h3><button class="wrist-row" data-action="newChat"><span class="row-icon">＋</span><span>新建对话</span></button>${threads.map(t=>`<button class="wrist-row" data-thread="${t.id}"><span class="row-icon">◷</span><span>${esc(t.title)}<small>${t.messages.length} 条消息</small></span></button>`).join('')}</div>`;
if(page==='chat'){const t=threads.find(x=>x.id===active);html=`<div class="wrist-list conversation"><h3>${esc(t.title)}</h3><div id="messages">${t.messages.length?t.messages.map(m=>`<div class="wrist-message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'你':'NOVA'}</small><p>${esc(m.text)}</p></div>`).join(''):'<p class="wrist-copy">轻触下方，开始说话</p>'}</div><button class="wrist-row blue-row" data-action="startVoice"><span class="row-icon">◉</span><span>语音回复</span></button><button class="wrist-row" data-action="quickReply"><span>继续展开</span></button></div>`;} 
if(page==='record')html=`<div class="record record-studio ${recording?'is-recording':seconds?'is-paused':'is-idle'}"><div class="record-topline"><span class="record-light"></span>${recording?'正在录制':seconds?'录制已暂停':'灵感速记'}</div><div class="record-clock" id="recordTime">${fmt(seconds)}</div><div class="record-signal"><canvas id="recordWave" aria-label="模拟录音波形"></canvas><span class="record-axis"></span></div><div class="record-caption">${recording?'让想法，自然流动':seconds?'暂停一下，思绪还在':'轻触开始，记下这一刻'}</div><div class="record-buttons"><button class="record-main" data-action="record" aria-label="${recording?'暂停录音':seconds?'继续录音':'开始录音'}">${recording?'<span class="pause-symbol"></span>':'<span class="mic-symbol">●</span>'}<span class="record-control-name">${recording?'暂停':seconds?'继续':'开始录音'}</span></button>${seconds||recording?'<button class="record-done" data-action="finishRecord" aria-label="完成录音"><span>✓</span><span class="record-control-name">完成</span></button>':''}</div><div class="record-button-labels"><span>${recording?'暂停':seconds?'继续':'开始录音'}</span>${seconds||recording?'<span>完成</span>':''}</div><div class="record-demo-label">模拟录音 · 不采集声音</div></div>`;
if(page==='transcript')html=`<div class="result-page"><h3>录音整理</h3><lg-segmented class="result-tabs" label="录音内容" value="${resultTab}" refraction="5"><button value="summary">摘要</button><button value="original">原文</button></lg-segmented><div class="result-scroll wrist-list" role="tabpanel" aria-label="${resultTab==='summary'?'摘要':'原文'}">${resultTab==='summary'?`<div class="result-intro"><span class="result-spark">✦</span><span>${summaries().length} 个重点<small>本地演示提炼</small></span></div>${summaries().map((x,i)=>`<section class="result-point"><div class="summary-counter">${String(i+1).padStart(2,'0')}</div><p>${esc(x)}</p></section>`).join('')}`:`<div class="original-meta">完整转写 · 演示内容</div><p class="original-text">${esc(transcript)}</p>`}<button class="wrist-row blue-row" data-action="${resultTab==='summary'?'copySummary':'copyText'}"><span>复制${resultTab==='summary'?'摘要':'原文'}</span></button><p class="wrist-note">右滑回到录音</p></div></div>`;
if(page==='settings')html=`<div class="wrist-list"><h3>设置</h3><button class="wrist-row" data-page="api"><span>AI 服务<small>${config.model?'已配置':'在手表上设置'}</small></span><span class="row-chevron">›</span></button><button class="wrist-row" data-action="toggleSpeaker"><span>语音播报</span><span class="switch ${speaker?'on':''}" aria-hidden="true"></span></button><button class="wrist-row" data-action="toggleHaptics"><span>触感反馈<small>演示偏好</small></span><span class="switch ${haptics?'on':''}" aria-hidden="true"></span></button></div>`;
if(page==='api')html=`<div class="wrist-list"><h3>AI 服务</h3>${[['url','服务地址'],['key','API 密钥'],['model','模型名称']].map(([id,label])=>`<button class="wrist-row" data-field="${id}"><span>${label}<small>${id==='key'?(config.key?'已填写 · ••••••':'未填写'):(esc(config[id])||'轻触设置')}</small></span><span class="row-chevron">›</span></button>`).join('')}<button class="wrist-row blue-row" data-action="validateConfig"><span>检查配置</span></button><button class="wrist-row" data-action="resetApi"><span>清空配置</span></button><p class="wrist-note">配置仅保存在当前演示内存</p></div>`;
if(page==='field'){const labels={url:'服务地址',key:'API 密钥',model:'模型名称'};html=`<form id="watchFieldForm" class="watch-field"><h3>${labels[fieldName]}</h3><div class="field-step">${['url','key','model'].indexOf(fieldName)+1} / 3</div><label for="watchFieldInput">${fieldName==='url'?'HTTP / HTTPS 地址':fieldName==='key'?'输入密钥，仅存内存':'输入模型名称'}</label><input id="watchFieldInput" name="value" type="${fieldName==='key'?'password':'text'}" value="${esc(config[fieldName])}" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="${labels[fieldName]}"><button class="primary" type="submit">保存</button><p>右滑取消本次修改</p></form>`;}
const resultRoot=$('#content .result-page');if(page==='transcript'&&resultRoot){const template=document.createElement('template');template.innerHTML=html;resultRoot.querySelector('.result-scroll').replaceWith(template.content.querySelector('.result-scroll'));const control=resultRoot.querySelector('lg-segmented');if(control)control.value=resultTab;}else{$('#content').innerHTML=html;}if($('#content canvas'))orb=new ParticleOrb($('#content canvas'),page==='voice'?voice:'idle');if(page==='voice')updateVoice();updateStateButtons();
}
// Chat is a child view; keep the main page inventory independent of its threads.
const originalShow=show;show=function(p){if(p==='chat'){orb?.destroy();if(page==='voice')stopVoice();if(page==='record')stopRecord();page='chat';history.replaceState(null,'','#chat');renderChat();return;}originalShow(p);};
function renderChat(){render();}
descriptions.chat=['一句接着一句。','常规聊天气泡，保留上下文。'];
function summaries(){return transcript.split(/[。！？\n]/).map(x=>x.trim()).filter(Boolean).slice(0,4);}
const voiceInfo={idle:['随时待命','有什么想聊的？','轻触粒子球，开始对话'],connecting:['正在连接','正在建立连接','让想法，慢慢靠近。'],listening:['正在聆听','我在听，请说。','“帮我梳理一下今天的工作安排。”'],thinking:['正在思考','让我想一想。','正在整理你的想法…'],speaking:['正在回答','可以这样开始。','先完成最重要的一项，再为沟通和复盘各留一段时间。'],error:['连接中断','暂时无法连接','轻触粒子球，重新开始。'],disabled:['麦克风已关闭','安静陪伴。','开启麦克风后继续对话。']};
function updateVoice(){const v=voiceInfo[voice];$('#voiceBadge').textContent=v[0];$('#voiceTitle').textContent=v[1];$('#voiceCaption').textContent=v[2];orb?.setState(voice);}
function setVoice(s){clearTimeout(voiceTimeout);voice=s;if(page!=='voice'){show('voice');}else updateVoice();updateStateButtons();}
function startVoice(){muted=false;voice='connecting';show('voice');voiceTimeout=setTimeout(()=>setVoice('listening'),1100);}
function updateStateButtons(){$('#states').innerHTML=Object.entries({idle:'待机',connecting:'连接',listening:'聆听',thinking:'思考',speaking:'回答',error:'断线',disabled:'静音'}).map(([s,t])=>`<button data-state="${s}" class="${(page==='voice'?voice:'idle')===s?'active':''}">${t}</button>`).join('');}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制');}catch{toast('浏览器未允许复制，可选中文字复制');}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.resultTab){resultTab=b.dataset.resultTab;render();return;}if(b.dataset.field){fieldName=b.dataset.field;show('field');return;}if(b.dataset.page){show(b.dataset.page);return;}if(b.dataset.thread){active=Number(b.dataset.thread);show('chat');return;}if(b.dataset.state){muted=b.dataset.state==='disabled';setVoice(b.dataset.state);render();return;}switch(b.dataset.action){case'quickReply':{const t=threads.find(x=>x.id===active);t.messages.push({role:'user',text:'继续展开'},{role:'assistant',text:'先选一个今天能完成的小目标，再把它拆成两到三个步骤。完成后回顾结果。（演示回复）'});renderChat();break;}case'back':show(({api:'settings',chat:'history',summary:'transcript',transcript:'record'})[page]||'home');break;case'startVoice':startVoice();break;case'nextVoice':if(muted){toast('请先开启麦克风');break;}setVoice(({idle:'connecting',connecting:'listening',listening:'thinking',thinking:'speaking',speaking:'listening',error:'connecting',disabled:'listening'})[voice]);break;case'endVoice':show('home');break;case'mute':muted=!muted;setVoice(muted?'disabled':'listening');render();break;case'speaker':speaker=!speaker;render();toast(speaker?'语音播报已开启':'语音播报已关闭');break;case'newChat':active=Date.now();threads.unshift({id:active,title:'新的对话',messages:[]});show('chat');break;case'clearChat':threads.find(t=>t.id===active).messages=[];renderChat();toast('当前会话已清空');break;case'record':if(recording)stopRecord();else{recording=true;recordInterval=setInterval(()=>{seconds++;if($('#recordTime'))$('#recordTime').textContent=fmt(seconds);},1000);}render();break;case'finishRecord':stopRecord();editing=false;resultTab='summary';show('transcript');break;case'editText':editing=true;render();break;case'saveText':if(!$('#editText').value.trim()){toast('请保留转写内容');break;}transcript=$('#editText').value.trim();editing=false;render();toast('已保存');break;case'summarize':if(editing){transcript=$('#editText').value.trim();editing=false;}if(!transcript){toast('请先填写转写内容');break;}show('summary');break;case'copyText':copy(editing?$('#editText').value:transcript);break;case'copySummary':copy(summaries().map((s,i)=>`${i+1}. ${s}`).join('\n'));break;case'toggleSpeaker':speaker=!speaker;render();break;case'toggleHaptics':haptics=!haptics;render();toast('已更新演示偏好');break;case'validateConfig':try{const u=new URL(config.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||!config.model.trim())throw Error();toast('格式正确，演示不发送请求');}catch{toast('请检查地址和模型名称');}break;case'checkConnection':toast('演示模式：尚未连接真实服务');break;case'resetApi':config={url:'',key:'',model:''};render();toast('已重置');break;}});
document.addEventListener('change',e=>{if(e.target.matches('lg-segmented.result-tabs')){resultTab=e.target.value;render();}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='watchFieldForm'){const value=$('#watchFieldInput').value.trim();if(fieldName==='url'&&value){try{const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error();}catch{toast('请输入有效的 HTTP(S) 地址');return;}}config[fieldName]=value;show('api');toast('已保存');return;}if(e.target.id==='chatForm'){const input=$('#message'),text=input.value.trim();if(!text){toast('请输入消息');return;}const t=threads.find(x=>x.id===active);t.messages.push({role:'user',text});if(t.title==='新的对话')t.title=text.slice(0,10);t.messages.push({role:'assistant',text:'收到你的想法：“'+text.slice(0,70)+'”。可以先明确目标，再拆成一个今天就能完成的小步骤。（演示回复）'});renderChat();}if(e.target.id==='apiForm'){const data=new FormData(e.target),url=data.get('url').trim(),model=data.get('model').trim();try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol)||!model||u.username||u.password)throw Error();config={url,key:data.get('key').trim(),model};toast('格式校验通过，已保存到当前内存');}catch{toast('请填写有效的 HTTP(S) 地址和模型名');}}});
$('#tour').onclick=()=>{startVoice();voiceTimeout=setTimeout(()=>{setVoice('listening');voiceTimeout=setTimeout(()=>{setVoice('thinking');voiceTimeout=setTimeout(()=>{setVoice('speaking');voiceTimeout=setTimeout(()=>setVoice('listening'),4500);},2000);},3000);},1100);};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape')show('home');if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const i=Math.max(0,pages.findIndex(x=>x[0]===page));show(pages[(i+(e.key==='ArrowDown'?1:pages.length-1))%pages.length][0]);}});
const mainPages=['home','record','history','settings'];
const parents={voice:'home',chat:'history',transcript:'record',summary:'transcript',api:'settings',field:'api'};
let touch;
function gestureEnd(x,y){if(!touch)return;const start=touch;touch=null;const dx=x-start.x,dy=y-start.y;if(Math.max(Math.abs(dx),Math.abs(dy))<65)return;const horizontal=Math.abs(dx)>Math.abs(dy)*1.2;if(!mainPages.includes(page)){if(horizontal&&dx>65)show(parents[page]||'home');return;}
if(!horizontal&&start.list){const el=start.list;if((dy<0&&start.top+el.clientHeight<el.scrollHeight-5)||(dy>0&&start.top>5))return;}
const i=mainPages.indexOf(page),next=(horizontal?dx<0:dy<0)?1:-1;show(mainPages[(i+next+mainPages.length)%mainPages.length]);}
function gestureStart(x,y,target){const list=target.closest('.wrist-list');touch={x,y,list,top:list?.scrollTop||0};}
$('#screen').addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.target.closest('input,textarea'))return;gestureStart(e.clientX,e.clientY,e.target);});
$('#screen').addEventListener('pointerup',e=>{if(e.pointerType!=='touch')gestureEnd(e.clientX,e.clientY);});
$('#screen').addEventListener('touchstart',e=>{if(e.target.closest('input,textarea'))return;const t=e.touches[0];gestureStart(t.clientX,t.clientY,e.target);},{passive:true});
$('#screen').addEventListener('touchend',e=>{const t=e.changedTouches[0];gestureEnd(t.clientX,t.clientY);},{passive:true});
$('#screen').addEventListener('click',e=>{if(touch&&Math.max(Math.abs(e.clientX-touch.x),Math.abs(e.clientY-touch.y))>65){e.preventDefault();e.stopPropagation();}},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopRecord();stopVoice();if(page==='record'||page==='voice')render();}});
show(location.hash.slice(1)||'home');
})();